    kind: '웹 파일 위변조',
    action: 'record',
    severity: 'Medium',
    attack: 'T1565.001 Stored Data Manipulation'
  },
  '100222': {
    kind: '실행형 파일 삭제',
    action: 'record',
    severity: 'High',
    attack: 'T1070.004 File Deletion'
  }
};

