  const j = item.json ?? {};
  const b = j.body ?? j;
  const events = b.alerts ?? b.events ?? (b.username ? [b] : []);
  for (const e of events) {
    const user = e.username ?? e.user;
    if (!user) continue;
    const cnt = e.count ?? e.fail_count ?? '?';
    out.push({ json: {
      username: user,
      reason: `브루트포스 자동 잠금: ${cnt}회 로그인 실패`,
      fail_count: Number(e.count ?? e.fail_count ?? 0),
