    const title = val(e.event_definition ?? e.rule ?? b.event_definition ?? b.rule, 'K09 패킷 트래픽 경보');
    const ip = val(e.src_ip ?? e.ip ?? e.event_key ?? e.group_key ?? b.src_ip ?? b.event_key);
    const severity = /K09-02|SYN/i.test(title) ? 'High' : 'Medium';
    const fields = [
      {name:'📌 탐지 규칙',value:safe(title),inline:false},
      {name:'🌐 출발지 IP',value:safe(ip),inline:true},
      {name:'⚙️ 대응',value:'탐지·경보 (자동 차단 미수행)',inline:true},
      {name:'🆔 Graylog 이벤트',value:safe(e.event_id ?? b.event_id),inline:false}
    ];
    for (const [key,label] of [['packet_count','패킷 수'],['tcp_syn_count','TCP SYN 수'],['unique_dst_ports','목적지 포트 종류'],['unique_dst_ips','목적지 IP 종류']]) {
      const v = e[key] ?? b[key];
      if (v !== undefined && v !== null && String(v) !== '') fields.push({name:'📊 '+label,value:safe(v),inline:true});
    }
    out.push({json:{
      username:'Security Alert Bot',allowed_mentions:{parse:[]},
      embeds:[{title:'['+severity.toUpperCase()+'] 📡 K09 패킷·트래픽 분석 경보',
        description:'실제 PCAP에서 추출한 통계에 대한 Graylog 탐지 이벤트입니다. 임계치 초과는 공격 확정을 의미하지 않습니다.',
        color: severity==='High' ? 0xED4245 : 0xFEE75C,fields:fields.slice(0,25),
        footer:{text:'Graylog → n8n → Discord | K09 탐지 알림'},timestamp:new Date().toISOString()}]
    }});
  }
}
return out;

// EX-01~08: Graylog 통합 이벤트를 Discord 경보로 변환; 모든 판단은 탐지·알림만 수행
const out = [];
const str = (v, fallback='정보 없음') => v === undefined || v === null || String(v).trim()==='' ? fallback : String(v);
const safe = (v, max=950) => str(v).replace(/@/g, '@\u200b').slice(0,max);
const labels = {
 'EX-01':'포트 스캔', 'EX-02':'SYN Flood 의심', 'EX-03':'저속 로그인 시도',
 'EX-04':'심야 로그인 성공', 'EX-05':'SQL Injection 의심',
 'EX-06':'내부 비인가 접근', 'EX-07':'로그 변조·삭제', 'EX-08':'Nikto 스캐너 식별'
};
for (const item of $input.all()) {
  const b = item.json?.body ?? item.json ?? {};
  const evs = Array.isArray(b.alerts) ? b.alerts : (Array.isArray(b.events) ? b.events : [b]);
  for (const e of evs) {
    if (!e || typeof e !== 'object') continue;
    const title = str(e.event_definition ?? e.rule ?? b.event_definition ?? b.rule, 'EX 보안 탐지 이벤트');
    const exId = (title.match(/EX-0[1-8]/i)||[])[0]?.toUpperCase() || '';
    const label = labels[exId] ?? '공방전 시나리오';
    const group = str(e.group_key ?? e.event_key ?? b.group_key ?? b.event_key);
    // 현재 공통 Notification은 event.key만 넘길 수 있으므로 IP/계정 종류를 단정하지 않음.
    const sevNum = Number(e.severity ?? b.severity);
    const severity = [ 'EX-02', 'EX-05', 'EX-06', 'EX-07' ].includes(exId) || sevNum >= 3 ? 'High' : 'Medium';
    const fields = [
      {name:'🛡️ 탐지 유형',value:safe(label),inline:true},
      {name:'📌 Graylog 규칙',value:safe(title),inline:false},
      {name:'🔑 그룹 키 (IP·계정·호스트)',value:safe(group),inline:true},
      {name:'⚙️ 대응',value:'탐지·알림 (자동 차단 미수행)',inline:true},
      {name:'🆔 이벤트 ID',value:safe(e.event_id ?? b.event_id),inline:false}
    ];
    out.push({json:{username:'Security Alert Bot',allowed_mentions:{parse:[]},embeds:[{
      title:'['+severity.toUpperCase()+'] 🚨 '+label,
      description:'Graylog 추가 공방전 시나리오 탐지 이벤트입니다. 공격 여부는 원본 로그와 함께 검토하세요.',
      color:severity==='High'?0xED4245:0xFEE75C, fields,
      footer:{text:'Graylog → n8n → Discord | EX-01~08 알림'},timestamp:new Date().toISOString()
    }]}});
  }
}
return out;
